import{_ as p,a0 as r,w as u,s as o,I as i,x as n,a1 as a,A as l,ao as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"將樹莓派 3B+ 變為 PriTunl VPN | LCTT x X-CMD","titleTemplate":false,"description":"將樹莓派 3B+ 變為 PriTunl VPN | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"將樹莓派 3B+ 變為 PriTunl VPN | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"將樹莓派 3B+ 變為 PriTunl VPN | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20190114 Turn a Raspberry Pi 3B- into a PriTunl VPN","title":"將樹莓派 3B+ 變為 PriTunl VPN","tag":"201901","desc":""},"relativePath":"201901/20190114 Turn a Raspberry Pi 3B- into a PriTunl VPN.md","filePath":"[post].md"}'),d={name:"201901/20190114 Turn a Raspberry Pi 3B- into a PriTunl VPN.md"};function g(b,s,h,k,m,f){const t=r("Link");return u(),o("div",null,[s[23]||(s[23]=i("h1",{id:"將樹莓派-3b-變為-pritunl-vpn",tabindex:"-1"},[n("將樹莓派 3B+ 變為 PriTunl VPN "),i("a",{class:"header-anchor",href:"#將樹莓派-3b-變為-pritunl-vpn","aria-label":"Permalink to “將樹莓派 3B+ 變為 PriTunl VPN”"},"​")],-1)),s[24]||(s[24]=i("blockquote",null,[i("p",null,"PriTunl 是一種 VPN 解決方案，適用於希望私密的訪問其網絡的小型企業和個人。")],-1)),s[25]||(s[25]=i("p",null,[i("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/life-raspberrypi_0.png?itok=Kczz87J2",alt:""})],-1)),i("p",null,[a(t,{href:"https://pritunl.com/"},{default:l(()=>[...s[0]||(s[0]=[n("PriTunl",-1)])]),_:1}),s[1]||(s[1]=n(" 是一款出色的 VPN 終端解決方案，非常適合希望以簡單快捷的方式私密的訪問網絡的小型企業和個人。它是開源的，基本的免費版本涵蓋最通用的簡單的實例，足以讓你快速入門。也有集成了活動目錄等高級功能的付費企業版。",-1))]),s[26]||(s[26]=e('<h3 id="有關樹莓派-3b-的特別注意事項" tabindex="-1">有關樹莓派 3B+ 的特別注意事項 <a class="header-anchor" href="#有關樹莓派-3b-的特別注意事項" aria-label="Permalink to “有關樹莓派 3B+ 的特別注意事項”">​</a></h3><p>PriTunl 的安裝通常也很簡單，但要在樹莓派 3B+ 上安裝 PriTunl 有點小複雜。比如，PriTunl 只提供了 AMD64 和 i386 架構的二進制文件，但樹莓派 3B+ 是 ARM 架構的，這意味着需要從源碼自行編譯可用於樹莓派 3B+ 的 PriTunl 可執行文件。不過，無需擔心，編譯過程很簡單，只需花一點時間執行幾行命令即可。</p><p>另一個問題：PriTunl 好像必須要是 64 位處理器架構，當我在 32 位操作系統上嘗試編譯的時候報錯了。但幸運的是，用於 ARM64 架構的 Ubuntu 18.04 測試版本可以安裝在樹莓派 3B+ 上。</p><p>同樣，樹莓派 3B+ 需要和其他樹莓派不同的引導程序。需要一組小複雜的命令來安裝更新樹莓派 3B+ 上必要的組件。</p><h3 id="安裝-pritunl" tabindex="-1">安裝 PriTunl <a class="header-anchor" href="#安裝-pritunl" aria-label="Permalink to “安裝 PriTunl”">​</a></h3><p>你可以先在樹莓派 3B+ 上安裝 64 位的操作系統來避免下面這些問題。此處需要一些必要的基礎知識如在樹莓派上執行命令列。</p><p>打開終端，用如下命令下載 Ubuntu 18.04 用於 ARM64 架構的測試版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://cdimage.ubuntu.com/releases/18.04/beta/ubuntu-18.04-beta-preinstalled-server-arm64+raspi3.img.xz</span></span></code></pre></div><p>將下載的固件解壓：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ xz -d ubuntu-18.04-beta-preinstalled-server-arm64+raspi3.xz</span></span></code></pre></div><p>將準備好的 SD 卡插入電腦讀卡槽，電腦會為 SD 卡分配一個驅動分配器號，例如 <code>/dev/sda</code> 或者 <code>/dev/sdb</code>。 輸入命令 <code>dmesg</code> 然後觀察屏幕上的最後幾行找到 SD 卡的驅動分配器。</p><p><strong>下一步小心操作，如果搞錯了驅動分配器號，可能會破壞你的系統。</strong></p><p>用如下命令往 SD 卡中寫入數據，將其中的 <code>&lt;DRIVE&gt;</code> 替換成你的 SD 驅動器號。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dd if=ubuntu-18.04-beta-preinstalled-server-arm64+raspi3.img of=&lt;DRIVE&gt; bs=8M</span></span></code></pre></div><p>完成上一步之後，將 SD 卡插入樹莓派 3B+ ，並啓動它。確保樹莓派 3B+ 是連網的，然後登錄系統，用户名/密碼：<code>ubuntu</code> / <code>ubuntu</code>。</p><p>在樹莓派上輸入以下命令以安裝一些編譯 PriTunl 所需的包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get -y install build-essential git bzr python python-dev python-pip net-tools openvpn bridge-utils psmisc golang-go libffi-dev mongodb</span></span></code></pre></div>',17)),i("p",null,[s[3]||(s[3]=n("和 PriTunl 標準源碼上的 ",-1)),a(t,{href:"https://github.com/pritunl/pritunl"},{default:l(()=>[...s[2]||(s[2]=[n("安裝説明",-1)])]),_:1}),s[4]||(s[4]=n(" 有一點不一樣。確保已經登錄進樹莓派然後切換到管理員賬户：",-1))]),s[27]||(s[27]=e(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo su -</span></span></code></pre></div><p>現在你應該在管理員賬户的目錄下，按如下命令來安裝 PriTunl 1.29.1914.98 版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export VERSION=1.29.1914.98</span></span>
<span class="line"><span>tee -a ~/.bashrc &lt;&lt; EOF</span></span>
<span class="line"><span>export GOPATH=\\$HOME/go</span></span>
<span class="line"><span>export PATH=/usr/local/go/bin:\\$PATH</span></span>
<span class="line"><span>EOF</span></span>
<span class="line"><span>source ~/.bashrc</span></span>
<span class="line"><span>mkdir pritunl &amp;&amp; cd pritunl</span></span>
<span class="line"><span>go get -u github.com/pritunl/pritunl-dns</span></span>
<span class="line"><span>go get -u github.com/pritunl/pritunl-web</span></span>
<span class="line"><span>sudo ln -s ~/go/bin/pritunl-dns /usr/bin/pritunl-dns</span></span>
<span class="line"><span>sudo ln -s ~/go/bin/pritunl-web /usr/bin/pritunl-web</span></span>
<span class="line"><span>wget https://github.com/pritunl/pritunl/archive/$VERSION.tar.gz</span></span>
<span class="line"><span>tar -xf $VERSION.tar.gz</span></span>
<span class="line"><span>cd pritunl-$VERSION</span></span>
<span class="line"><span>python2 setup.py build</span></span>
<span class="line"><span>pip install -r requirements.txt</span></span>
<span class="line"><span>python2 setup.py install --prefix=/usr/local</span></span></code></pre></div><p>現在，不出意外的話應該可以啓動 MongoDB 和 PriTunl 的 systemd 單元了。假如現在還是以管理員賬户登錄的話，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl daemon-reload</span></span>
<span class="line"><span>systemctl start mongodb pritunl</span></span>
<span class="line"><span>systemctl enable mongodb pritunl</span></span></code></pre></div>`,5)),i("p",null,[s[6]||(s[6]=n("大功告成！你現在可以登錄 PriTunl 的用户界面並按照官網上的 ",-1)),a(t,{href:"https://docs.pritunl.com/docs/configuration-5"},{default:l(()=>[...s[5]||(s[5]=[n("安裝和配置手冊",-1)])]),_:1}),s[7]||(s[7]=n(" 來配置它了。",-1))]),s[28]||(s[28]=i("hr",null,null,-1)),i("p",null,[s[9]||(s[9]=n("via: ",-1)),a(t,{href:"https://opensource.com/article/19/1/pritunl-vpn-raspberry-pi"},{default:l(()=>[...s[8]||(s[8]=[n("https://opensource.com/article/19/1/pritunl-vpn-raspberry-pi",-1)])]),_:1})]),i("p",null,[s[14]||(s[14]=n("作者：",-1)),a(t,{href:"https://opensource.com/users/stevereaver"},{default:l(()=>[...s[10]||(s[10]=[n("Stephen Bancroft",-1)])]),_:1}),s[15]||(s[15]=n(" 選題：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[11]||(s[11]=[n("lujun9972",-1)])]),_:1}),s[16]||(s[16]=n(" 譯者：",-1)),a(t,{href:"https://github.com/jrglinux"},{default:l(()=>[...s[12]||(s[12]=[n("jrg",-1)])]),_:1}),s[17]||(s[17]=n(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:l(()=>[...s[13]||(s[13]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[20]||(s[20]=n("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[18]||(s[18]=[n("LCTT",-1)])]),_:1}),s[21]||(s[21]=n(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:l(()=>[...s[19]||(s[19]=[n("Linux中國",-1)])]),_:1}),s[22]||(s[22]=n(" 榮譽推出",-1))])])}const y=p(d,[["render",g]]);export{c as __pageData,y as default};
